package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;import java.util.*;
final class DownloadActions {
 static void start(Activity a,String id,String name,String kind,boolean refresh,boolean force){String owner=DownloadSync.owner(a);try(SyncDb db=new SyncDb(a)){db.ensure(owner,id,name,kind);db.active(owner,id,true);try{AutoDownloads.seedCached(a,owner,id,db);}catch(Exception ignored){}db.status(owner,id,"Очередь сохранена. Проверка без уведомления; прогресс появится при скачивании.");}SyncRequests.put(a,owner,id,refresh,force,true);AutoDownloads.kick(a);AutoDownloads.retry(a);SoundFlowUi.notice(a,"Очередь сохранена. Уведомление появится при скачивании.");}
 static void choose(Activity a,String user,String id,String name,String kind,Runnable changed){if(AutoDownloads.enabled(a,user,id)){disable(a,user,id,name,kind,changed);return;}new AlertDialog.Builder(a).setTitle(name).setItems(new String[]{"Скачать один раз","Включить автозагрузку"},(d,w)->{if(w==0)start(a,id,name,kind,true,true);else AutoDownloads.toggle(a,user,id,name,kind);changed.run();}).setNegativeButton("Отмена",null).show();}
 static void disable(Activity a,String user,String id,String name,String kind,Runnable changed){new AlertDialog.Builder(a).setTitle("Выключить автозагрузку?").setMessage("Сохранить скачанные треки этого списка или удалить их? Копии, нужные другим спискам загрузки, будут сохранены.").setNegativeButton("Отмена",null).setPositiveButton("Оставить треки",(d,w)->{if(AutoDownloads.enabled(a,user,id))AutoDownloads.toggle(a,user,id,name,kind);changed.run();}).setNeutralButton("Удалить треки",(d,w)->{if(AutoDownloads.enabled(a,user,id))AutoDownloads.toggle(a,user,id,name,kind);try(SyncDb db=new SyncDb(a)){PlaybackService playing=PlaybackService.instance;if(playing!=null){Library library=new Library(a);Library.Track selected=library.find(playing.current);if(selected!=null)for(Library.Track t:db.tracks(user,id))if(t.id().equals(selected.id())&&!db.otherReference(user,id,t.id())){playing.stopForLocalChange();break;}}}new Thread(()->{int removed=0,failed=0;try(SyncDb db=new SyncDb(a)){OfflineStore store=new OfflineStore(a);for(Library.Track t:db.tracks(user,id)){if(!user.equals(DownloadSync.owner(a)))break;if(db.otherReference(user,id,t.id()))continue;Library.Track copy=store.bySource(t.id());if(copy!=null)try{PlaybackService s=PlaybackService.instance;if(s!=null&&(s.current.equals(copy.uri)||s.current.equals(t.uri))){failed++;continue;}store.remove(copy.uri);db.state(user,id,t.id(),"REMOVED","");removed++;}catch(Exception e){failed++;}}db.removePlan(user,id);}final int n=removed,f=failed;new Handler(Looper.getMainLooper()).post(()->{if(!a.isFinishing()){SoundFlowUi.notice(a,"Удалено: "+n+(f>0?". Занятых/недоступных: "+f:""));changed.run();}});},"SoundFlow-offline-cleanup").start();changed.run();}).show();}
}
